user nginx;
worker_processes auto;
events { worker_connections 1024; }
http {
  include /etc/nginx/mime.types;
  default_type application/octet-stream;
  client_max_body_size 1G;
  keepalive_timeout 180;
  proxy_connect_timeout 180s;
  proxy_send_timeout 180s;
  proxy_read_timeout 180s;

  server {
    listen 8080;
    server_name localhost;
    port_in_redirect off;
    absolute_redirect off;

    auth_request_set $auth_user $upstream_http_x_auth_request_user;
    auth_request_set $auth_email $upstream_http_x_auth_request_email;
    auth_request_set $groups $upstream_http_x_auth_request_groups;
    auth_request_set $access_token $upstream_http_x_auth_request_access_token;
    proxy_set_header X-Forwarded-User $auth_user;
    proxy_set_header X-Forwarded-Email $auth_email;
    proxy_set_header X-Forwarded-groups $groups;
    proxy_set_header X-Forwarded-Access-Token $access_token;
    proxy_set_header Host $http_host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Forwarded-Proto $http_x_forwarded_proto;
    proxy_http_version 1.1;
    proxy_set_header Upgrade $http_upgrade;
    proxy_set_header Connection "upgrade";

    location /oauth2/ { proxy_pass ${ENV_OAUTH2_PROXY_URL}/oauth2/; }
    location = /oauth2/auth { proxy_pass ${ENV_OAUTH2_PROXY_URL}/oauth2/auth; proxy_pass_request_body off; proxy_set_header Content-Length ""; proxy_set_header X-Original-URL $scheme://$http_host$request_uri; }
    location = /oauth2/callback { proxy_pass ${ENV_OAUTH2_PROXY_URL}/oauth2/callback; }
    location = /logout { return 302 ${ENV_AUTH_URL}realms/${ENV_KEYCLOAK_REALM}/protocol/openid-connect/logout?client_id=${ENV_KEYCLOAK_OIDC_CLIENT_ID}&post_logout_redirect_uri=${ENV_APP_URL}logout/after; }
    location = /logout/after { return 302 ${ENV_APP_URL}oauth2/sign_out; }

    location / { auth_request /oauth2/auth; error_page 401 = @error401; proxy_pass ${ENV_FPGEN_API_URL}/; }
    location /review/ { auth_request /oauth2/auth; error_page 401 = @error401; proxy_pass http://fpgen-admin-review-ui:8080/; }
    location /api/ { auth_request /oauth2/auth; error_page 401 = @error401; proxy_pass ${ENV_FPGEN_API_URL}/; }
    location /files/ { auth_request /oauth2/auth; error_page 401 = @error401; proxy_pass http://fpgen-data-file-viewer:8080/files/; }
    location /exports/ { auth_request /oauth2/auth; error_page 401 = @error401; proxy_pass ${ENV_FPGEN_API_URL}/v1/proposals/; }
    location @error401 { return 302 /oauth2/start?rd=$scheme://$http_host$request_uri; }
  }
}
